def dedup(xs):
    seen = set()
    result = []
    for x in xs:
        if x not in seen:
            seen.add(x)
            result.append(x)
    return result
```

```python
def bsearch(xs, x):
    left, right = 0, len(xs) - 1
    while left <= right:
        mid = (left + right) // 2
        if xs[mid] < x:
            left = mid + 1
        elif xs[mid] > x:
            right = mid - 1
        else:
            return mid
    return -1
```

