```python
def second_max(xs):
    unique_xs = set(xs)
    if len(unique_xs) < 2:
        return None
    unique_xs.remove(max(unique_xs))
    return max(unique_xs)
```

```python
def flatten(xs):
    result = []
    for el in xs:
        if isinstance(el, list):
            result.extend(flatten(el))
        else:
            result.append(el)
    return result
```

